function __run336(t,i,press){/* pkgRUN ASK 336 (W2 7013, D1-D5; all four seats AGREE): an [L2] paragraph that names no verse reference of its own (each of its [L2] lines, W2 7046 M1) binds also to the run of [L1] paragraphs directly before it; [L3]/[L4]/headings end the run; it only adds verses the block quotes as [L1]. ASK 342 (iii), W3 7086 a-d: a paragraph that names a book-less c:v, v. N, vv. N-M or verse N binds to those verses, with the book (and, for v./verse, the chapter) taken from the [L1] run only when the run holds one book (one chapter); otherwise it binds to nothing */try{if(press)return [];const SEP=/\n[ \t]*\n/g;let ps=0,m;while((m=SEP.exec(t))&&m.index<i)ps=m.index+m[0].length;{const PL=t.slice(ps,i).split('\n');if(!/^[\s>*_#-]*$/.test(PL[PL.length-1])||!PL.slice(0,-1).every(x=>/^[\s>*_-]*\[L2\]/.test(x)))return [];}const rest=t.slice(i).search(/\n[ \t]*\n/);const para=t.slice(ps,rest<0?t.length:i+rest);if(refsIn(para).length)return [];const __pz=para.replace(/\b[GH]\d+/g,'');const __BL=[];try{for(const r of REFP.parse(__pz,{scoped:true}))if(!r.book&&!r.ctx)__BL.push(r);}catch(e){return [];}const __VV=[...__pz.matchAll(/(?<![\w.])(?:vv?\.|verses?\b)\s*(\d{1,3})(?:\s*[–—-]\s*(\d{1,3}))?(?![\d:])/gi)];const P=t.slice(0,ps).split(/\n[ \t]*\n/);let k=P.length-1;while(k>=0&&!P[k].trim())k--;const out=[];for(;k>=0;k--){const L=P[k].split('\n').filter(x=>x.trim());if(!L.length)break;const hd=x=>{const h=x.match(/^[\s>*_-]*\[L1\]\s*[*_]*\s*([^"“]{0,200})/);return h?refsIn(h[1]):null;};const r0=hd(L[0]);if(!r0||!r0.length)break;const got=[].concat(r0,...L.slice(1).map(x=>hd(x)||[]));out.unshift(...got);}if(!__BL.length&&!__VV.length)return [...new Set(out)];const __bk=new Set(out.map(k=>k.replace(/\s\d+:\d+$/,'')));if(__bk.size!==1)return [];const __B=[...__bk][0];const __res=[];const __runCh=new Set(out.map(k=>(k.match(/\s(\d+):\d+$/)||[])[1]));for(const r of __BL)if(!__runCh.has(String(r.c)))return [];for(const r of __BL){const z=r.v2-r.v1>12?r.v1:r.v2;for(let v=r.v1;v<=z;v++)__res.push(__B+' '+r.c+':'+v);}if(__VV.length){const __ch=new Set(out.map(k=>(k.match(/\s(\d+):\d+$/)||[])[1]));if(__ch.size!==1)return [];const __C=[...__ch][0];for(const x of __VV){const a=+x[1],b=x[2]?+x[2]:a;const z=(b<a||b-a>12)?a:b;for(let v=a;v<=z;v++)__res.push(__B+' '+__C+':'+v);}}return [...new Set(__res)];}catch(e){return [];}}
